"""Regenerate classes_gen.go and testdata/classes.json from the real Python re module:
python3 -I internal/pyre/testdata/gen_classes.py

classes_gen.go: the code-point ranges re matches with \\s, \\d and \\w in a str pattern
(Python 3.15, Unicode 17), which pyre writes as explicit classes because regexp2's own
classes differ (.NET \\s lacks \\x1c-\\x1f, and the Go Unicode tables are older).
classes.json: for each class pattern and flags, the count and SHA-256 of the code points it
matches over all of U+0000..U+10FFFF without surrogates; the anchor cases ($, \\Z, ^ with
and without MULTILINE) and Integrante3's call-site patterns: the finditer spans on each subject."""
import hashlib
import json
import os
import re
import unicodedata

HERE = os.path.dirname(os.path.abspath(__file__))
POINTS = [c for c in range(0x110000) if not 0xD800 <= c <= 0xDFFF]
CLASS_PATTERNS = [r"\s", r"\S", r"\d", r"\D", r"\w", r"\W", r"[\s]", r"[^\s]", r"[\d_]", r"[^\d]", r"[\w-]",
                  r"[^\w]", r"[\S\d]", r"[^\W\d]", r"[\D]", r"[x\s]", r"(?a)\w", r"(?a)[^\s]"]
ANCHORS = [r"a$", r"$", r"(?m)a$", r"(?m)$", r"a\Z", r"\Z", r"(?m)^", r"^", r"a\z", r"\n$", r"(?s).$"]
ANCHOR_SUBJECTS = ["a", "a\n", "a\n\n", "a\nb", "a\nb\n", "ba\r\n", "", "\n"]

# Integrante3's call sites (i3-field-tools-c: secaudit/winacl.go, greenmaxmatrix/panels.go and
# px.go, greenmaxtablero/transform.go) with sample lines: finditer spans and groups.
HOA = r'Relay\$5b[0-9]+\$5d\$2eBO/(?:active|inactive|auto)"'
POP = r'PopupBinding\b[^>]*\bord="slot:R[0-9]+"'
CALLSITES = [
    (r"(?i)^(.*?):((?:\([A-Z]+(?:,[A-Z]+)*\))+)\s*$",
     ["C:\\Niagara\\security BUILTIN\\Administrators:(OI)(CI)(F)\n", "NT AUTHORITY\\SYSTEM:(I)(F)",
      "Todos:(RX)\u3000", "Users:(OI)(CI)(rx) \x1c\n", "no ace here", "x:(F,R)\n\n", "a:b:(M)"]),
    (r"(?i)(?:^|[\s\\])(Authenticated Users|Users|Everyone"
     r"|Usuarios autentificados|Usuarios autenticados|Usuarios|Todos"
     r"|Usuários autenticados|Usuários"
     r"|Utilisateurs authentifiés|Utilisateurs|Tout le monde"
     r"|Authentifizierte Benutzer|Benutzer|Jeder"
     r"|Utenti autenticati|Utenti)\n?$",
     ["C:\\x BUILTIN\\Users\n", "Todos", "NT AUTHORITY\\Authenticated Users", "tout le monde\n",
      "\u00a0Jeder", "MyUsers", "Utenti\n\n", "x\x1dUSUÁRIOS"]),
    (r"^Relay\[([0-9]+)\]\.BO$", ["Relay[3].BO", "Relay[12].BO\n", "Relay[3].BO\n\n", "xRelay[3].BO"]),
    (r"^(?:Schedule|R)([0-9]+)$", ["Schedule4", "R12\n", "R", "Schedule4x"]),
    (r"^(?:SchdlGM0*[0-9]+\s+R|HorR)([0-9]+)$", ["SchdlGM02 R5", "SchdlGM2\u2003R12\n", "HorR7", "SchdlGM2R5",
                                                 "SchdlGM2\x1cR5"]),
    (r"^labelR([0-9]+)$", ["labelR3", "labelR3\n"]),
    (r"^tabR([0-9]+)$", ["tabR10", "tabR"]),
    (r"^GM0*([0-9]+)ilum$", ["GM03ilum", "GM10ilum\n", "GMilum"]),
    (r"^GreenMAX0*([0-9]+)\s+Tab(AL[0-9]+)", ["GreenMAX03 TabAL12 x", "GreenMAX3\x1fTabAL1", "GreenMAX3TabAL1"]),
    (r'<Picture layout="([0-9.]+),([0-9.]+),60\.0,30\.0"[^>]*>\s*'
     r'<ValueBinding ord="slot:Relay\$5b([0-9]+)\$5d\$2eBO">\s*<IBooleanToSimple',
     ['<Picture layout="10.0,20.5,60.0,30.0" a="b">\n  <ValueBinding ord="slot:Relay$5b7$5d$2eBO">\n'
      '  <IBooleanToSimple/>', '<Picture layout="1,2,60.0,30.0"><ValueBinding ord="slot:R1">']),
    (r"(?s)\s*<ImageButton\b[^>]*>\s*<ActionBinding\b[^>]*\bord=\"slot:" + HOA +
     r"[^>]*>.*?</ActionBinding>\s*</ImageButton>",
     ['<x/>\n  <ImageButton id="1">\n <ActionBinding k="v" ord="slot:Relay$5b3$5d$2eBO/auto" p="q">\n'
      '<a/>\n</ActionBinding>\n</ImageButton><y/>\n<ImageButton><ActionBinding ord="slot:Relay$5b4$5d$2eBO/active">'
      '</ActionBinding></ImageButton>']),
    (r"(?s)\s*<Picture\b[^>]*>\s*<" + POP + r"[^>]*/>\s*</Picture>",
     ['<a/>\n <Picture x="1">\n  <PopupBinding k="v" ord="slot:R12" z="w"/>\n </Picture>\n<b/>']),
]


def ranges(pattern):
    rx, out, start, prev = re.compile(pattern), [], None, None
    for c in range(0x110000):
        if rx.match(chr(c)):
            if start is None:
                start = c
            elif c != prev + 1:
                out.append((start, prev))
                start = c
            prev = c
    out.append((start, prev))
    return out


def digest(pattern, flags):
    rx = re.compile(pattern, flags)
    hits = [c for c in POINTS if rx.fullmatch(chr(c))]
    return {"pattern": pattern, "flags": flags, "count": len(hits),
            "sha256": hashlib.sha256(",".join(map(str, hits)).encode()).hexdigest()}


def go_table(name, rs):
    pairs = [f"0x{lo:X}, 0x{hi:X}" for lo, hi in rs]
    lines = ["\t" + ", ".join(pairs[i:i + 6]) + "," for i in range(0, len(pairs), 6)]
    return f"var {name} = []rune{{\n" + "\n".join(lines) + "\n}\n"


def main():
    src = ("// Code generated by testdata/gen_classes.py from Python's re (Unicode "
           f"{unicodedata.unidata_version}); DO NOT EDIT.\n\npackage pyre\n\n"
           "// Inclusive (lo, hi) code-point pairs of the str-pattern classes \\s, \\d and \\w.\n\n"
           + go_table("pySpaceRanges", ranges(r"\s")) + "\n" + go_table("pyDigitRanges", ranges(r"\d")) + "\n"
           + go_table("pyWordRanges", ranges(r"\w")))
    with open(os.path.join(HERE, "..", "classes_gen.go"), "w", encoding="utf-8") as fh:
        fh.write(src)
    anchors = []
    for flags in (0, re.IGNORECASE):
        for p in ANCHORS:
            rx = re.compile(p, flags)
            anchors.append({"pattern": p, "flags": flags,
                            "spans": [[list(m.span()) for m in rx.finditer(s)] for s in ANCHOR_SUBJECTS]})
    callsites = []
    for p, subjects in CALLSITES:
        rx = re.compile(p)
        callsites.append({"pattern": p, "subjects": subjects, "matches": [
            [[list(m.span())] + [list(m.span(g)) if m.group(g) is not None else None
                                 for g in range(1, rx.groups + 1)] for m in rx.finditer(s)] for s in subjects]})
    data = {"unicode": unicodedata.unidata_version, "subjects": ANCHOR_SUBJECTS,
            "classes": [digest(p, f) for f in (0, re.IGNORECASE) for p in CLASS_PATTERNS], "anchors": anchors,
            "callsites": callsites}
    with open(os.path.join(HERE, "classes.json"), "w", encoding="utf-8") as fh:
        fh.write("{" + f'"unicode": {json.dumps(data["unicode"])}, "subjects": {json.dumps(data["subjects"])},\n')
        fh.write('"classes": [\n' + ",\n".join(json.dumps(c) for c in data["classes"]) + "\n],\n")
        fh.write('"anchors": [\n' + ",\n".join(json.dumps(a) for a in data["anchors"]) + "\n],\n")
        fh.write('"callsites": [\n' + ",\n".join(json.dumps(c, ensure_ascii=False) for c in data["callsites"])
                 + "\n]}\n")


if __name__ == "__main__":
    main()
